// Emit Sample Identities (mock trigger payload) — LOCAL variant.
// Cloud instead receives these from a Webhook (POST body). Three identities that
// exercise every gate branch: create (not in HubSpot), enrich (stale), skip (fresh).
const rows = [
  { email: "jamie.rivera@exampleracing.example", object_type: "contacts" },  // CREATE
  { email: "alex.taylor@exampleco.example", object_type: "contacts" },       // ENRICH
  { email: "sam.fresh@examplemedia.example", object_type: "contacts" }       // SKIP
];
return rows.map((r) => ({ json: r }));

// normalizeEmail.js — pure-JS email normalization for n8n Code nodes.
//
// normalizeEmailBasic does a BASIC syntactic check + trim/lowercase only. The
// authoritative validation is the external rapid-email-verifier API downstream;
// applyEmailVerification maps that verifier's response onto the row. This mirrors
// src/normalizer.py normalize_email closely enough for identity/dedupe parity:
// obviously-malformed -> null, otherwise trimmed+lowercased.

function normalizeEmailBasic(raw) {
  if (raw === null || raw === undefined) return null;
  const s = String(raw).trim().toLowerCase();
  if (s === "") return null;
  // Basic shape: local@domain.tld, no spaces, one @, a dotted domain.
  // Deliberately conservative — the verifier API is the real authority.
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s)) return null;
  return s;
}

// Map a rapid-email-verifier result onto the row. `verifierResult` shape:
//   { status: "VALID"|"PROBABLY_VALID"|"INVALID_FORMAT"|"INVALID_DOMAIN"|"DISPOSABLE",
//     aliasOf?: "canonical@example.com" }
// Returns the fields to merge onto the row.
function applyEmailVerification(row, verifierResult) {
  const status = (verifierResult && verifierResult.status) || "INVALID_FORMAT";
  const alias = verifierResult && verifierResult.aliasOf;
  const raw = row ? row.email : undefined;

  // aliasOf is the canonical address when the verifier resolved one.
  const canonical = alias
    ? normalizeEmailBasic(alias)
    : normalizeEmailBasic(raw);

  const valid = status === "VALID" || status === "PROBABLY_VALID";

  return {
    email_normalized: valid ? canonical : normalizeEmailBasic(raw),
    email_valid: valid,
    email_status: status,
    needs_review_reason: valid ? null : `email verifier: ${status}`,
  };
}

// n8n/code/matchProposal.js — pure-JS match-lane routing and proposal shaping.
//
// Phase 36 Plan 01 (36-CONTEXT.md §7 step 1). `Build Identity` stamps a single `lane`
// value per enrichment row so every downstream routing IF and adapter reads ONE source
// of truth instead of re-deriving its own predicate (36-CONTEXT.md
// <assumption_delta_decision>: "lane becomes the one field that names a row's
// identity-resolution strategy"). Pure, deterministic, no n8n globals — mirrors
// listExpansion.js/providerSelection.js, inlined into a Code node by the builder's
// inline() (Code nodes cannot require() siblings).
//
// laneOf(row) -> "fetch_by_id" | "email" | "name" | "none"
//   The `fetch_by_id` branch mirrors `IF Bare Event`'s boolean expression exactly
//   (scripts/build_cloud_workflows.py, `IF Bare Event` node build):
//     !!$('Build Identity').item.json.object_id &&
//     !$('Build Identity').item.json.identity_keys.email
//   If the two predicates ever drift, a row is routed to one lane and filtered into
//   another and silently disappears (36-CONTEXT.md key_links).

function isPlainObject(value) {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

// Trims a string field before the truthiness check so a whitespace-only value (e.g.
// companyName: "   ") is never mistaken for a present identity key. Non-strings pass
// through untouched — object_id may legitimately be a number.
function trimmedOrValue(value) {
  return typeof value === "string" ? value.trim() : value;
}

function laneOf(row) {
  const r = isPlainObject(row) ? row : {};
  const identityKeys = isPlainObject(r.identity_keys) ? r.identity_keys : {};
  const objectId = r.object_id;
  const email = trimmedOrValue(identityKeys.email);
  const lastName = trimmedOrValue(identityKeys.lastName);
  const companyName = trimmedOrValue(identityKeys.companyName);

  if (objectId && !email) return "fetch_by_id";
  if (email) return "email";
  if (lastName && companyName) return "name";
  return "none";
}

// --- n8n wrapper: normalise the incoming identity into HubSpot search keys ---
return $input.all().map((it) => {
  const row = it.json;
  const email = normalizeEmailBasic(row.email);
  const identity_keys = {
    email,
    domain: row.domain || (email ? email.split("@")[1] : null),
    linkedin_url: row.linkedin_url || null,
    // Name+company let the providers match when no email is in hand (the common
    // pre-enrichment case). ZoomInfo/Apollo accept firstName+lastName+companyName.
    firstName: row.firstname || row.first_name || null,
    lastName: row.lastname || row.last_name || null,
    companyName: row.company || row.companyName || null,
  };
  return { json: { ...row,
    object_type: row.object_type || "contacts",
    identity_keys,
    // 36-CONTEXT.md §5A: each adapter filters to ITS OWN lane before index-aligning
    // against its own HTTP node — this one stamped field is the single source of
    // truth plan 36-02's match-lane routing IFs read too, so routing and filtering
    // provably cannot disagree.
    lane: laneOf({ object_id: row.object_id, identity_keys }),
  }};
});

// HubSpot Search (MOCK) — LOCAL variant only.
// Cloud uses a real HubSpot search node; here we return canned existing records so
// enrichmentGate exercises every branch:
//   jamie.rivera@... -> {} (no record)              => CREATE
//   alex.taylor@...  -> stale jobtitle + no mobile   => ENRICH
//   sam.fresh@...    -> fresh + complete + valid     => SKIP
const CANNED = {
  "jamie.rivera@exampleracing.example": {},
  "alex.taylor@exampleco.example": {
    email: "alex.taylor@exampleco.example",
    jobtitle: "Analyst",
    lv_jobtitle_verified_at: "2025-01-01T00:00:00Z",
    mobilephone: ""
  },
  "sam.fresh@examplemedia.example": {
    email: "sam.fresh@examplemedia.example",
    jobtitle: "Producer",
    lv_jobtitle_verified_at: "2026-07-01T00:00:00Z",
    mobilephone: "+61412000000",
    lv_mobilephone_verified_at: "2026-07-01T00:00:00Z"
  }
};
return $input.all().map((it) => {
  const row = it.json;
  const email = (row.identity_keys && row.identity_keys.email) || null;
  const existingRecord = CANNED[email] || {};
  return { json: { ...row, existingRecord } };
});

