  // Basic shape: local@domain.tld, no spaces, one @, a dotted domain.
  // Deliberately conservative — the verifier API is the real authority.
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s)) return null;
  return s;
}

// Map a rapid-email-verifier result onto the row. `verifierResult` shape:
//   { status: "VALID"|"PROBABLY_VALID"|"INVALID_FORMAT"|"INVALID_DOMAIN"|"DISPOSABLE",
//     aliasOf?: "canonical@example.com" }
// Returns the fields to merge onto the row.
function applyEmailVerification(row, verifierResult) {
  const status = (verifierResult && verifierResult.status) || "INVALID_FORMAT";
  const alias = verifierResult && verifierResult.aliasOf;
  const raw = row ? row.email : undefined;

  // aliasOf is the canonical address when the verifier resolved one.
  const canonical = alias
    ? normalizeEmailBasic(alias)
    : normalizeEmailBasic(raw);

  const valid = status === "VALID" || status === "PROBABLY_VALID";

  return {
    email_normalized: valid ? canonical : normalizeEmailBasic(raw),
    email_valid: valid,
    email_status: status,
    needs_review_reason: valid ? null : `email verifier: ${status}`,
  };
}

// normalizeProviders.js — pure-JS provider-response → common candidate shape.
//
// toCandidates(providerName, rawResponse, objectType) flattens ONE provider's raw
// API response into an array of common-shape candidates, one per usable field:
//   { field, source, value, normalizedValue, accuracy, recencyDate }
// where `field` is the canonical HubSpot property, `value` is the raw provider
// value, `normalizedValue` is the cross-check key (E.164 phone / lowercased email /
// revenue band / employee band / NAICS code), `accuracy` (0-1) is derived from the
// provider's per-field quality signal (see ENRICHMENT-WORKFLOW-PLAN.md §2 A-table),
// and `recencyDate` is the field's freshness date for the recency term.
//
// NO npm. Reuses normalizePhoneAU / normalizeEmailBasic from siblings. Revenue and
// employee band normalizers are local (mirror src/normalizer.py) — small enough to
// keep here rather than import a fourth module.


// Country NAME -> ISO2 (Apollo returns names like "United States"; Lusha gives country_iso2
// directly). Unmapped -> undefined, so normalizePhone falls back to its AU heuristic.
const _COUNTRY_ISO2 = {
  australia: "AU", "new zealand": "NZ", "united states": "US", "united states of america": "US",
  canada: "CA", "united kingdom": "GB", "great britain": "GB", england: "GB", ireland: "IE",
  india: "IN", singapore: "SG",
};
function _iso2(nameOrCode) {
  if (!nameOrCode) return undefined;
  const v = String(nameOrCode).trim();
  if (/^[A-Za-z]{2}$/.test(v)) return v.toUpperCase();  // already ISO2
  return _COUNTRY_ISO2[v.toLowerCase()];
}

// ---- local value normalizers (mirror src/normalizer.py band logic) ----------
// Parse a revenue value (number OR range string like "10M-25M") to lower-bound
// dollars, then map to the CLAUDE.md revenue bands. Range strings use the LOWER
// bound so "10M-25M" -> 5-50M, "50M-100M" -> 50-500M.
function _revenueToDollars(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "number") return value;
  const s = String(value);
  const m = s.match(/([\d.]+)\s*([kmb]?)/i); // first magnitude
  if (!m) return null;
  let n = parseFloat(m[1]);
  if (Number.isNaN(n)) return null;
  const unit = (m[2] || "").toLowerCase();
  if (unit === "k") n *= 1e3;
  else if (unit === "m") n *= 1e6;
  else if (unit === "b") n *= 1e9;
  return n;
}

function normalizeRevenueBand(value) {
  const v = _revenueToDollars(value);
  if (v === null) return null;
  // ZERO IS NO-DATA, NOT A BAND. Apollo returns `organization_revenue: 0.0` (a number,
  // not null) for every company it has no revenue figure for — confirmed live against
  // mrc.racing.com, whose HubSpot record already carries annualrevenue 206,078,000.
  // Banding that 0 as "<1M" is worse than saying nothing: "<1M" scores 0 ICP points
  // where the truthful "50-500M" scores +10, so a missing figure silently reads as a
  // disqualifying one. Guarded here rather than at the Apollo call site because
  // ZoomInfo's `revenue * 1000` collapses to 0 the same way. Downstream, a null band is
  // dropped by Merge Company's `v != null` candidate filter — no candidate is emitted.
  if (v <= 0) return null;
  if (v < 1e6) return "<1M";
  if (v < 5e6) return "1-5M";
  if (v < 50e6) return "5-50M";
  if (v < 500e6) return "50-500M";
  if (v < 750e6) return "500-750M";
  if (v < 1e9) return "750M-1B";
  if (v < 1.2e9) return "1B-1.2B";
  return "1.2B+";
}

function normalizeEmployeeBand(value) {
  if (value === null || value === undefined || value === "") return null;
  // Already a band string (e.g. ZoomInfo employeeRange "201-500") -> pass through, with
  // whitespace around the hyphen collapsed: live Lusha returns "51 - 200", and the spaced
  // form is NOT an lv_employee_band enum value ("51-200" is).
  if (typeof value === "string" && !/^\d+$/.test(value.trim())) {
    return value.trim().replace(/\s*-\s*/g, "-");
  }
  const v = parseInt(value, 10);
  if (Number.isNaN(v)) return null;
  // Same zero-is-no-data rule as normalizeRevenueBand: a headcount of 0 is a provider
  // saying "unknown", never a real company, and "1-9" is a lie that reads as a real
  // (tiny) size to the scorer.
  if (v <= 0) return null;
  if (v <= 9) return "1-9";
  if (v <= 50) return "10-50";
  if (v <= 200) return "51-200";
  if (v <= 500) return "201-500";
  if (v <= 1000) return "501-1000";
  return "1001+";
}

function normalizeCountryRegion(value) {
  if (!value) return null;
  const v = String(value).trim().toLowerCase();
  if (["australia", "au", "aus"].includes(v)) return "AU";
  if (["new zealand", "nz"].includes(v)) return "NZ";
  return "Other";
}

function _clamp01(n) {
  if (n < 0) return 0;
  if (n > 1) return 1;
  return n;
}

// ---- per-provider accuracy helpers (ENRICHMENT-WORKFLOW-PLAN.md §2) ---------
const APOLLO_EMAIL_A = { verified: 1.0, guessed: null, pending: 0.3, unavailable: 0, bounced: 0 };

function apolloEmailAccuracy(raw) {
  const status = raw.email_status;
  let a;
  if (status === "guessed") {
    // guessed = 0.5 * extrapolated_confidence (default confidence 1.0 when absent).
    let ex = raw.extrapolated_email_confidence;
    if (ex === null || ex === undefined) ex = 1.0;
    if (ex > 1) ex = ex / 100; // tolerate 0-100 scale
    a = 0.5 * ex;
  } else {
    a = APOLLO_EMAIL_A[status];
    if (a === null || a === undefined) a = 0; // unknown status -> no trust
  }
  if (raw.email_domain_catchall) a *= 0.6; // catchall penalty
  return _clamp01(a);
}

const LUSHA_EMAIL_CONF = { "A+": 1.0, A: 0.8 };
function lushaEmailAccuracy(e) {
  // Live v2 email item uses emailConfidence/emailType; flat fixtures use confidence/type.
  const conf = e.confidence != null ? e.confidence : e.emailConfidence;
  const type = e.type != null ? e.type : e.emailType;
  let a = LUSHA_EMAIL_CONF[conf];
  if (a === null || a === undefined) a = 0.4; // null/unknown grade
  if (type && String(type).toLowerCase() !== "work") a *= 0.8; // private/personal
  return _clamp01(a);
}

// ---- provider mappers -------------------------------------------------------
function _push(out, field, source, value, normalizedValue, accuracy, recencyDate) {
  if (value === null || value === undefined || value === "") return;
  out.push({ field, source, value, normalizedValue, accuracy: _clamp01(accuracy), recencyDate: recencyDate || null });
}

// Prefer human-readable industry text over a raw NAICS code; a bare numeric code is never
// a valid `industry` text value (NORM-01). Precedence: the NAICS entry's own `.name` text
// when the entry is an object carrying one; otherwise the provider's industry text fallback
// (first element when the fallback is an array); otherwise null — no candidate is fabricated
// from a bare code.
function _industryText(naicsEntry, textFallback) {
  if (naicsEntry && typeof naicsEntry === "object" && naicsEntry.name) {
    return { raw: naicsEntry.name, key: _norm(naicsEntry.name) };
  }
  const fallback = Array.isArray(textFallback) ? textFallback[0] : textFallback;
  if (fallback) return { raw: fallback, key: _norm(fallback) };
  return null; // bare numeric code, no name, no fallback text -> skip, don't fabricate
}

// COPY-02 (18-VERIFICATION.md GAP 2, D-GAP2-provider/D-GAP2-othervalue): a provider's OWN
// department field, when present, is the persona_group producer -- no invented title-to-
// persona taxonomy. Takes the first element when the value is an array. Lusha's live
// "Other" label is a semantically-empty non-signal (case-insensitive compare) -- a
// persona group of "Other" is not a classification, it renders in a HubSpot view as
// though a decision were made when none was, which is strictly worse for the RevOps
// reviewer than the property staying blank. Returns null rather than fabricating a value
// from a non-value, mirroring _industryText's contract.
function _personaGroup(departments) {
  const first = Array.isArray(departments) ? departments[0] : departments;
  if (!first) return null;
  if (String(first).trim().toLowerCase() === "other") return null;
  return first;
}

// _lushaRecord(rawResponse, objectType) -- Lusha envelope adapter, sibling to _zoomRecord().
// The v3 Enrichment API (the live contract as of 2026-07-30, confirmed against a real
// api.lusha.com session and recorded in docs/LUSHA-V3-CONTRACT.md) is a flat
// { requestId, results: [...], billing } envelope, positionally aligned with the request's
// single-item array (this waterfall sends one identity per call, so results[0] is safe with
// no match-back key). A per-result `error` (no-match/error shape, contract §9), a missing or
// non-array `results`, a non-object input and a null input all resolve to {} -- zero
// candidates, never a throw (skip-not-retry, CLAUDE.md Sec 26.1). v2's envelope handling
// (a plural contactId-keyed `{contacts:{...}}` map and a singular `{contact:{data}}}` form)
// was retired in this phase (Plan 20-03) ahead of v2's 2026-11-18 sunset -- no v2-shaped
// response can reach this function once Plan 05's redeploy ships.
//
// v3 field names already match the intermediate shape the extraction logic below reads
// (emails[].email/.type/.confidence, phones[].number/.type/.doNotCall, jobTitle.title/
// .seniority/.departments) for CONTACTS, so _lushaV3Contact only renames the one field that
// differs: location.countryIso2 (v3, camelCase) -> location.country_iso2 (the snake_case key
// the extraction's region lookup reads). For COMPANIES, v3's revenueRange/employeeCount ship
// as {min,max}/{exact,min,max} objects rather than the [lo,hi] array or plain number the
// extraction expects, and industry classification is a flat `industry` string rather than
// naicsCodes -- _lushaV3Company does that reshaping.
function _lushaV3Contact(entry) {
  const loc = entry.location || {};
  return {
    id: entry.id,
    emails: entry.emails,
    phones: entry.phones,
    jobTitle: entry.jobTitle,
    location: { ...loc, country_iso2: loc.countryIso2 },
    updateDate: entry.updateDate,
  };
}

function _lushaV3Company(entry) {
  const rr = entry.revenueRange;
  const revenueRange = rr && typeof rr === "object" && !Array.isArray(rr) ? [rr.min, rr.max] : rr;
  let ec = entry.employeeCount;
  if (ec && typeof ec === "object") {
    ec = ec.exact != null ? ec.exact
      : (ec.min != null && ec.max != null ? Math.round((ec.min + ec.max) / 2) : null);
  }
  return {
    id: entry.id,
    revenueRange,
    employeeCount: ec,
    mainIndustry: entry.industry,
    location: entry.location,
    updateDate: entry.updateDate,
  };
}

function _lushaRecord(rawResponse, objectType) {
  const raw = rawResponse;
  if (!raw || typeof raw !== "object") return {};

  if (Array.isArray(raw.results)) {
    const entry = raw.results[0];
    if (!entry || typeof entry !== "object" || entry.error) return {};
    return objectType === "companies" ? _lushaV3Company(entry) : _lushaV3Contact(entry);
  }

  // Bare/flat fallback: offline unit tests pass a record's fields directly with no envelope
  // at all (e.g. `{ phones: [...] }`). Not a v2 envelope shape -- v3 has no wrapper either
  // once unwrapped above, so this is the same pass-through both versions relied on.
  return raw;
}

function lushaCandidates(rawResponse, objectType) {
  const out = [];
  const src = "lusha";
  const raw = _lushaRecord(rawResponse, objectType) || {};
  const updated = raw.updateDate;
  const region = raw.location && (raw.location.country_iso2 || raw.location.country); // ISO2 or name
  if (objectType === "contacts") {
    // Live: emailAddresses/phoneNumbers with emailType/phoneType; fixtures: emails/phones with type.
    for (const e of raw.emailAddresses || raw.emails || []) {
      _push(out, "email", src, e.email, normalizeEmailBasic(e.email), lushaEmailAccuracy(e), e.updateDate || updated);
    }
    for (const p of raw.phoneNumbers || raw.phones || []) {
      if (p.doNotCall) continue; // suppress (not just downscore) per §2
      const norm = normalizePhone(p.number, _iso2(region));
      if (!norm) continue; // null-drop: un-normalizable phone never reaches HubSpot
      const t = String(p.phoneType || p.type || "").toLowerCase();
      const acc = t === "mobile" || t === "direct" ? 0.8 : 0.5;
      const field = t === "mobile" ? "mobilephone" : "phone";
      _push(out, field, src, p.number, norm, acc, p.updateDate || updated);
    }
    if (raw.jobTitle) {
      // No per-field grade for Lusha title -> ungraded base 0.6.
      _push(out, "jobtitle", src, raw.jobTitle.title, _norm(raw.jobTitle.title), 0.6, updated);
      _push(out, "seniority", src, raw.jobTitle.seniority, _norm(raw.jobTitle.seniority), 0.6, updated);
      // COPY-02: persona_group producer, reading Lusha's own department field off the
      // same jobTitle object the block already destructures. Unprefixed field name here
      // (read-side key, mirrors seniority/jobtitle above) -- the PN-1 lv_ rename happens
      // only at the merge/canonical-write boundary, which this file never touches.
      const persona = _personaGroup(raw.jobTitle.departments);
      _push(out, "persona_group", src, persona, _norm(persona), 0.6, updated);
    }
  } else {
    // company firmographics — no per-field grade -> base 0.6. `raw.company` serves the
    // contacts/person endpoint's nested company object (extraction, not envelope -- kept
    // regardless of envelope version); the retired v2 `/v2/company` `data`-wrapper term was
    // dropped here in Plan 20-03 Task 3 (docs/LUSHA-V3-CONTRACT.md §5 confirms v3's companies
    // response is flat, no `data` key). `raw` itself is the v3 adapter's own flat output.
    const co = raw.company || raw;
    const rev = Array.isArray(co.revenueRange) ? co.revenueRange[0] : co.revenueRange;
    _push(out, "lv_revenue_band", src, rev, normalizeRevenueBand(rev), 0.6, updated);
    // Live /v2/company returns the headcount as `employees` ("51 - 200", a spaced range
    // string); companySize/employeeCount are null there and only appear in the fixtures.
    const emp = Array.isArray(co.companySize)
      ? co.companySize[co.companySize.length - 1]
      : (co.companySize != null ? co.companySize
        : (co.employeeCount != null ? co.employeeCount : co.employees));
    _push(out, "lv_employee_band", src, emp, normalizeEmployeeBand(emp), 0.6, updated);
    const naics0 = (co.naicsCodes || [])[0];
    const industry = _industryText(naics0, co.mainIndustry);
    _push(out, "industry", src, industry && industry.raw, industry && industry.key, 0.6, updated);
    const country = (co.location && co.location.countryIso2) || co.countryIso2;
    _push(out, "lv_country_region_normalized", src, country, normalizeCountryRegion(country), 0.6, updated);
  }
  return out;
}

// lushaRecordId(rawResponse, objectType) -- extracts the opaque Lusha record identifier
// (docs/LUSHA-V3-CONTRACT.md §4/§5: `results[i].id`) for Plan 04's HubSpot staging
// properties (lusha_contact_id / lusha_company_id). A deliberate SIBLING of
// lushaCandidates(), not a field inside it -- REQ-lusha-v3-normalize requires the
// candidate stream stay field-identical, so the id must never enter scoreCandidates as a
// candidate. Reuses the SAME _lushaRecord() envelope adapter Plan 03 built (a no-match, a
// per-record error, a missing/non-object entry, `{}` and `null` all resolve through that
// adapter to {} / no id). Never throws; returns null for anything that is not a non-empty
// string id.
function lushaRecordId(rawResponse, objectType) {
  try {
    const rec = _lushaRecord(rawResponse, objectType);
    const id = rec && rec.id;
    return typeof id === "string" && id.trim() !== "" ? id : null;
  } catch (e) {
    return null;
  }
}

function apolloCandidates(raw, objectType) {
  const out = [];
  const src = "apollo";
  // Live people/match nests the record under `person`; flat fixtures don't. Read
  // through `person` so both shapes work (mirrors the org fallback below).
  const person = raw.person || raw;
  const updated = person.updated_at || raw.updated_at;
  if (objectType === "contacts") {
    _push(out, "email", src, person.email, normalizeEmailBasic(person.email), apolloEmailAccuracy(person), updated);
    const region = _iso2(person.country || (person.organization && person.organization.country));
    for (const p of person.phone_numbers || []) {
      if (p.dnc_status || p.doNotCall) continue; // suppress
      const norm = normalizePhone(p.sanitized_number, region);
      if (!norm) continue; // null-drop: un-normalizable phone never reaches HubSpot
      const status = p.status || p.status_cd;
      const acc = status === "valid_number" ? 1.0 : 0.5;
      const t = String(p.type || "").toLowerCase();
      const field = t === "mobile" ? "mobilephone" : "phone";
      _push(out, field, src, p.sanitized_number, norm, acc, updated);
    }
    _push(out, "jobtitle", src, person.title, _norm(person.title), 0.6, updated);
    _push(out, "seniority", src, person.seniority, _norm(person.seniority), 0.6, updated);
    // COPY-02: same persona_group producer, reading Apollo's own department field.
    const persona = _personaGroup(person.departments);
    _push(out, "persona_group", src, persona, _norm(persona), 0.6, updated);
  } else {
    const org = (raw.person && raw.person.organization) || raw.organization || raw.org || raw;
    // Live org revenue is `organization_revenue` (number); flat fixtures use `annual_revenue`.
    const revenue = org.annual_revenue != null ? org.annual_revenue : org.organization_revenue;
    _push(out, "lv_revenue_band", src, revenue, normalizeRevenueBand(revenue), 0.6, updated);
    _push(out, "lv_employee_band", src, org.estimated_num_employees, normalizeEmployeeBand(org.estimated_num_employees), 0.6, updated);
    // Apollo org industry is free-text (no NAICS in this contract) -> lowercase text key.
    _push(out, "industry", src, org.industry, _norm(org.industry), 0.6, updated);
  }
  return out;
}

// Unwrap the GTM enrich response envelope to a flat contact record.
// Live GTM (confirmed 200): { data: [ { attributes:{...fields}, meta:{matchStatus}, id } ] }
// (JSON:API). We flatten attributes and lift matchStatus/id up. Older/flat fixture
// envelopes ({data:[rec]}, {data:{result:[{data:[rec]}]}}, flat) still pass through.
function _zoomRecord(raw) {
  if (!raw || typeof raw !== "object") return raw || {};
  let rec = raw;
  if (Array.isArray(raw.data)) rec = raw.data[0] || {};
  else if (raw.data && typeof raw.data === "object" && raw.data.attributes) rec = raw.data;
  if (rec && rec.attributes) {
    return { ...rec.attributes, id: rec.id,
      matchStatus: (rec.meta && rec.meta.matchStatus) || rec.attributes.matchStatus };
  }
  const r = raw.data != null ? raw.data : raw;
  if (Array.isArray(r)) return r[0] || {};
  if (r && Array.isArray(r.result)) {
    const first = r.result[0];
    if (first && Array.isArray(first.data)) return first.data[0] || {};
    return first || {};
  }
  return r;
}

function zoominfoCandidates(rawResponse, objectType) {
  const out = [];
  const src = "zoominfo";
  const raw = _zoomRecord(rawResponse) || {};
  const recency = raw.validDate || raw.lastUpdatedDate;
  if (objectType === "contacts") {
    const fullMatch = raw.matchStatus === "FULL_MATCH" || raw.matchStatus === undefined;
    // matchStatus != FULL_MATCH drops person fields entirely (§2).
    if (!fullMatch) return out;
    // Live contactAccuracyScore is a STRING ("91.0"); coerce before the /100.
    const scoreNum = Number(raw.contactAccuracyScore);
    const acc = Number.isFinite(scoreNum) && raw.contactAccuracyScore !== "" && raw.contactAccuracyScore != null
      ? scoreNum / 100 : 0.6;
    _push(out, "email", src, raw.email, normalizeEmailBasic(raw.email), acc, recency);
    // Phones: structural 0.8 (no per-field grade) per §2 "mobilePhone present=0.8".
    // ZoomInfo GTM enrich returns no country field, so region falls back to the AU
    // heuristic; E.164 numbers pass through, non-AU national is null-dropped (safe).
    // (Add a verified `country` outputField later to parse non-AU ZoomInfo nationals.)
    const region = _iso2(raw.country);
    const phone = normalizePhone(raw.phone, region);
    if (phone) _push(out, "phone", src, raw.phone, phone, 0.8, recency);
    const mobile = normalizePhone(raw.mobilePhone, region);
    if (mobile) _push(out, "mobilephone", src, raw.mobilePhone, mobile, 0.8, recency);
    _push(out, "jobtitle", src, raw.jobTitle, _norm(raw.jobTitle), acc, recency);
    // managementLevel is an array (["Director"]) in the live GTM response; take the first.
    const ml = Array.isArray(raw.managementLevel) ? raw.managementLevel[0] : raw.managementLevel;
    _push(out, "seniority", src, ml, _norm(ml), acc, recency);
  } else {
    // UNITS: GTM `revenue` is in THOUSANDS, not dollars — confirmed live against three
    // records (Racing NSW 268163 + revenueRange "$250 mil. - $500 mil."; ZoomInfo 1254000
    // + "$1 bil. - $5 bil."; FanDuel 14050000 + "Over $5 bil."), and Apollo independently
    // reports Racing NSW annual_revenue 268000000 dollars. Feeding the raw number to
    // normalizeRevenueBand (which expects dollars) banded every company 1000x low —
    // FanDuel's $14b read as "5-50M". Prefer the unambiguous `revenueRange` string;
    // fall back to revenue*1000.
    const ziRev = raw.revenueRange != null && raw.revenueRange !== ""
      ? raw.revenueRange
      : (typeof raw.revenue === "number" ? raw.revenue * 1000 : null);
    _push(out, "lv_revenue_band", src, ziRev, normalizeRevenueBand(ziRev), 0.6, recency);
    // employeeCount is an exact integer; employeeRange ("100 - 250") is NOT an
    // lv_employee_band enum value, so it is only a last resort.
    _push(out, "lv_employee_band", src, raw.employeeCount != null ? raw.employeeCount : raw.employeeRange,
      normalizeEmployeeBand(raw.employeeCount != null ? raw.employeeCount : raw.employeeRange), 0.6, recency);
    const ziCountry = _iso2(raw.country);
    _push(out, "lv_country_region_normalized", src, raw.country,
      normalizeCountryRegion(ziCountry || raw.country), 0.6, recency);
    // Live GTM naicsCodes are OBJECTS ({id,name}, most-general first); the flat fixtures
    // are bare code strings. String(obj) would have staged "[object Object]" as industry.
    // primaryIndustry is an array in the live response (["Hospitality", "Sports Teams ..."]).
    // NORM-01: prefer the NAICS entry's own human-readable name over its bare numeric code;
    // a code is never a valid industry text value (see _industryText).
    const naics0 = (raw.naicsCodes || [])[0];
    const industry = _industryText(naics0, raw.primaryIndustry);
    _push(out, "industry", src, industry && industry.raw, industry && industry.key, 0.6, recency);
  }
  return out;
}

function _norm(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim().toLowerCase();
  return s === "" ? null : s;
}

const MAPPERS = { lusha: lushaCandidates, apollo: apolloCandidates, zoominfo: zoominfoCandidates };

function toCandidates(providerName, rawResponse, objectType) {
  const mapper = MAPPERS[String(providerName || "").toLowerCase()];
  if (!mapper || !rawResponse) return [];
  return mapper(rawResponse, objectType === "companies" ? "companies" : "contacts");
}

// scoreEnrichment.js — pure-JS field-level best-of-breed scorer for n8n Code nodes.
//
// scoreCandidates(candidates, opts) groups common-shape candidates (from
// normalizeProviders.toCandidates) by canonical `field`, scores EACH candidate
//   value_score = wA·A + wR·R + wG·G + wT·T          (ENRICHMENT-WORKFLOW-PLAN.md §2)
// and returns the argmax per field with full provenance, plus a flat merge-ready
// winners map ({field: value}) that slots straight into mergeContacts.
//
//   A — accuracy   : candidate.accuracy (already provider-derived).
//   R — recency    : 1 - min(ageDays/staleCeiling, 1) from recencyDate.
//                    NO recencyDate -> neutral 0.5 (freshness unknown, not penalised).
//   G — agreement  : fraction of OTHER sources whose normalizedValue equals this one
//                    (cross-check / consensus). Single source -> 0.
//   T — source trust: base rank /100 (zoominfo .85, lusha .80, apollo .75). Tiebreaker.
//
// PURE + DETERMINISTIC: inject `opts.now` (ISO) — no Date.now in the scoring math.
// `opts.mode`: 'scored_all' (default) scores everything given; 'scored_cost_aware'
// scores only sources in `opts.calledSources` (caller owns the early-exit decision).

const DEFAULT_WEIGHTS = { wA: 0.45, wR: 0.2, wG: 0.25, wT: 0.1 };
const DEFAULT_TRUST = { zoominfo: 0.85, lusha: 0.8, apollo: 0.75 };
const DEFAULT_STALE_CEILING = 365;

function _ageDays(recencyDate, nowIso) {
  if (!recencyDate) return null;
  const then = Date.parse(recencyDate);
  const now = Date.parse(nowIso);
  if (Number.isNaN(then) || Number.isNaN(now)) return null;
  return (now - then) / 86400000;
}

function _recency(recencyDate, nowIso, staleCeiling) {
  const age = _ageDays(recencyDate, nowIso);
  if (age === null) return 0.5; // unknown freshness -> neutral
  const ceil = staleCeiling > 0 ? staleCeiling : DEFAULT_STALE_CEILING;
  return 1 - Math.min(age / ceil, 1);
}

function _eq(a, b) {
  if (a === null || a === undefined || b === null || b === undefined) return false;
  return String(a) === String(b);
}

function scoreCandidates(candidates, opts) {
  opts = opts || {};
  const w = Object.assign({}, DEFAULT_WEIGHTS, opts.weights || {});
  const trust = Object.assign({}, DEFAULT_TRUST, opts.trust || {});
  const staleCeilings = opts.staleCeilings || {};
  const nowIso = opts.now || new Date().toISOString();
  const mode = opts.mode || "scored_all";

  let pool = candidates || [];
  if (mode === "scored_cost_aware" && Array.isArray(opts.calledSources)) {
    const called = new Set(opts.calledSources.map((s) => String(s).toLowerCase()));
    pool = pool.filter((c) => called.has(String(c.source).toLowerCase()));
  }

  // Group by canonical field.
  const groups = {};
  for (const c of pool) {
    (groups[c.field] || (groups[c.field] = [])).push(c);
  }

  const best = {};
  const winners = {};
  const ranked = {};

  for (const field of Object.keys(groups)) {
    const group = groups[field];
    const ceil = staleCeilings[field] || DEFAULT_STALE_CEILING;
    let top = null;
    const scoredGroup = [];

    for (const c of group) {
      // Agreement: OTHER candidates (distinct sources) whose normalizedValue matches.
      const agreedBy = [];
      for (const o of group) {
        if (o === c) continue;
        if (o.source === c.source) continue;
        if (_eq(o.normalizedValue, c.normalizedValue)) agreedBy.push(o.source);
      }
      const otherSources = new Set(group.filter((o) => o.source !== c.source).map((o) => o.source));
      const A = c.accuracy;
      const R = _recency(c.recencyDate, nowIso, ceil);
      const G = otherSources.size ? new Set(agreedBy).size / otherSources.size : 0;
      const T = trust[String(c.source).toLowerCase()] != null ? trust[String(c.source).toLowerCase()] : 0.6;
      const score = w.wA * A + w.wR * R + w.wG * G + w.wT * T;

      const cand = {
        field,
        value: c.value,
        normalizedValue: c.normalizedValue,
        source: c.source,
        score,
        components: { A, R, G, T },
        agreedBy: [...new Set(agreedBy)],
      };

      if (top === null || _beats(cand, top, trust)) top = cand;
      scoredGroup.push(cand);
    }

    best[field] = top;
    winners[field] = top.value;
    // ranked[field] — D4 (Phase 15.5): every scored candidate, not just the argmax,
    // sorted with the SAME deterministic tie-break _beats already uses. Purely additive:
    // existing callers destructuring {best}/{winners} are unaffected.
    ranked[field] = scoredGroup.slice().sort((a, b) => (_beats(a, b, trust) ? -1 : (_beats(b, a, trust) ? 1 : 0)));
  }

  return { best, winners, ranked };
}

// Deterministic tie-break: higher score, then higher trust, then source name.
function _beats(a, b, trust) {
  if (a.score !== b.score) return a.score > b.score;
  const ta = trust[String(a.source).toLowerCase()] || 0;
  const tb = trust[String(b.source).toLowerCase()] || 0;
  if (ta !== tb) return ta > tb;
  return String(a.source) < String(b.source);
}

// --- n8n wrapper: toCandidates(all 3) -> scoreCandidates -> best-per-field ---
return $input.all().map((it) => {
  const row = it.json;
  const p = row.providers;
  if (!p) return { json: { ...row, scored: null, gap_flag: false } };  // skip branch
  const ot = row.object_type || "contacts";
  const cands = [
    ...toCandidates("lusha", p.lusha, ot),
    ...toCandidates("apollo", p.apollo, ot),
    ...toCandidates("zoominfo", p.zoominfo, ot),
  ];
  const gap_flag = cands.length === 0;  // ALL sources returned nothing -> flag manual
  const { best, winners } = scoreCandidates(cands, { now: new Date().toISOString() });
  // Plan 04: the matched Lusha record id rides as its OWN row field (never a candidate --
  // it must never enter scoreCandidates/the merge policy). Omitted entirely when null, so
  // an absent id can never become an empty-string write over a previously stored id.
  const lushaId = lushaRecordId(p.lusha, ot);
  const lusha_ids = lushaId
    ? (ot === "companies" ? { lusha_company_id: lushaId } : { lusha_contact_id: lushaId })
    : null;
  return { json: { ...row, scored: { best, winners }, gap_flag, ...(lusha_ids ? { lusha_ids } : {}) } };
});

// mergeContacts.js — pure-JS DETERMINISTIC non-clobber merge for n8n Code nodes.
//
// Mirrors the DETERMINISTIC parts of src/merge_policy.py (deterministic_gate +
// source_metadata) for a single upload candidate per field.
// NO Haiku / NO Sonnet — the LLM classification/validation stages that merge_policy
// runs after the gate are intentionally omitted here (n8n Code nodes cannot call
// them; escalation happens in a downstream node). So the decision IS the gate's
// decision. Source = "csv" @ confidence 80 (matches src/ingest.py row_to_provider_result).
//
// Email can NEVER land in canonicalPatch on this enrich path (belt-and-braces: the
// manual_protected class + the 95 threshold already prevent it, and an explicit
// guard enforces it regardless of policy edits).
//
// PROVENANCE MODEL (Phase 15): per-field metadata/staging is ONE provenance object keyed
// by field ({source, confidence, verified_at, validation_status, value}), not flat
// `{field}_source`/`{provider}_{field}` properties. The caller (the
// build_cloud_workflows.py wrapper) serializes it ONCE via stableStringify() into
// `lv_contact_enrichment_provenance`, alongside the 2 cache-key datetimes this module
// surfaces on `cacheKeys` for jobtitle / mobilephone.

// Default contacts field policy (source of truth: config/field_policy.yaml `contacts`).
// PN-1: linkedin_url/persona_group are NOT HubSpot-native (absent from the verified-
// native list) -> lv_-prefixed canonical field keys.
const DEFAULT_CONTACT_POLICY = {
  email:           { class: "manual_protected",  min_confidence: 95 },
  phone:           { class: "fill_blank_only",   min_confidence: 80 },
  mobilephone:     { class: "fill_blank_only",   min_confidence: 85 },
  jobtitle:        { class: "stale_refreshable", min_confidence: 75 },
  lv_linkedin_url: { class: "fill_blank_only",   min_confidence: 85 },
  seniority:       { class: "system_owned",      min_confidence: 75 },
  lv_persona_group:{ class: "system_owned",      min_confidence: 75 },
};

function _isBlank(v) {
  return v === null || v === undefined || v === "" ||
         (Array.isArray(v) && v.length === 0);
}

function _nowIso() {
  return new Date().toISOString();
}

// Recursively sort object keys before JSON.stringify — see mergeCompanies.js's
// stableStringify() (identical implementation, duplicated per the existing
// self-contained-per-Code-node pattern this repo already uses for _isBlank/_nowIso/etc.)
// for the full parity-with-Python rationale.
function _sortedForStringify(value) {
  if (Array.isArray(value)) return value.map(_sortedForStringify);
  if (value !== null && typeof value === "object") {
    const out = {};
    for (const k of Object.keys(value).sort()) out[k] = _sortedForStringify(value[k]);
    return out;
  }
  return value;
}

function stableStringify(value) {
  return JSON.stringify(_sortedForStringify(value));
}

// The 2 contact cache-key fields (queryable datetimes) — everything else rides in the
// provenance blob.
const CONTACT_CACHE_KEY_FIELDS = {
  jobtitle: "lv_jobtitle_verified_at",
  mobilephone: "lv_mobilephone_verified_at",
};

// Does this field+value need an evidence URL before it may promote? (Phase 16.2 Task 2
// additive port of mergeCompanies.js's _needsEvidence — inert for every contact field
// today: DEFAULT_CONTACT_POLICY declares no require_evidence_url/require_evidence_url_for
// entries, so this only bites once Plan 02's research fold supplies a policy that does.)
function _needsEvidence(policy, value) {
  if (!policy) return false;
  if (policy.require_evidence_url === true) return true;
  const gated = policy.require_evidence_url_for;
  if (Array.isArray(gated)) return gated.indexOf(value) !== -1;
  return false;
}

// Deterministic gate — single candidate, mirrors merge_policy.deterministic_gate.
// has_conflict is always false with one candidate, so the conflict branch is dropped.
// Phase 16.2 Task 2 (additive): evidenceUrl/value are new trailing params, mirroring
// mergeCompanies.js's _gate — every existing call site below still passes only the
// first 4 args, so evidenceUrl/value are undefined and _needsEvidence(...) is false.
function _gate(field, currentValue, confidence, policy, evidenceUrl, value) {
  const fieldClass = (policy && policy.class) || "fill_blank_only";
  const minConfidence = (policy && policy.min_confidence != null) ? policy.min_confidence : 80;

  if (confidence < minConfidence) {
    return { decision: "needs_review",
             reason: `Best confidence ${confidence} below threshold ${minConfidence}.` };
  }
  // Evidence gate runs BEFORE the class branches: an unevidenced claim is never
  // promotable no matter how system_owned the field is (mirrors mergeCompanies.js,
  // CLAUDE.md §21.3) — inert today since no contact policy entry requires evidence.
  if (_needsEvidence(policy, value) && _isBlank(evidenceUrl)) {
    return { decision: "needs_review",
             reason: `Field ${field}=${value} requires an evidence URL; none supplied.` };
  }
  if (fieldClass === "manual_protected") {
    return { decision: "stage_only", reason: "Field is manual_protected." };
  }
  if (fieldClass === "review_required") {
    return { decision: "needs_review", reason: "Field requires review." };
  }
  if (fieldClass === "system_owned" || fieldClass === "score_output" || fieldClass === "veto_output") {
    return { decision: "promote", reason: "System-owned field passed confidence threshold." };
  }
  if (fieldClass === "fill_blank_only") {
    if (_isBlank(currentValue)) {
      return { decision: "promote", reason: "Current value blank and candidate passed threshold." };
    }
    return { decision: "stage_only", reason: "Current value exists and field is fill_blank_only." };
  }
  if (fieldClass === "stale_refreshable") {
    if (_isBlank(currentValue)) {
      return { decision: "promote", reason: "Current value blank and candidate passed threshold." };
    }
    return { decision: "needs_review", reason: "Refresh candidate requires review in MVP." };
  }
  return { decision: "stage_only", reason: "Default conservative behavior." };
}

function _statusFor(decision) {
  // Deterministic (no LLM) validation_status from source_registry vocabulary.
  return decision === "needs_review" ? "human_review_required" : "provider_only";
}

// mergeContacts(existingProps, candidateRow, fieldPolicy?, opts?)
//   existingProps: current HubSpot contact properties (the record being enriched)
//   candidateRow:  canonical-keyed upload row (post column-map + normalization)
//   fieldPolicy:   contacts policy block; defaults to DEFAULT_CONTACT_POLICY
//   opts:          { source="csv", confidence=80, evidence={field: url},
//                    confidenceByField={field: number} }
//                  Phase 16.2 Task 2 (additive port of mergeCompanies.js's opts,
//                  mergeCompanies.js:150-169): `evidence` is a per-field evidence-URL
//                  map (absent = no evidence); `confidenceByField` overrides the flat
//                  `confidence` for one field. The ONE existing caller (ENRICH_MERGE's
//                  provider `mergeContacts(existing, candidate, undefined, {source,
//                  confidence})`) omits both keys and is therefore byte-identical —
//                  proven by tests/n8n/mergeContacts.test.mjs.
function mergeContacts(existingProps, candidateRow, fieldPolicy, opts) {
  existingProps = existingProps || {};
  candidateRow = candidateRow || {};
  const policy = fieldPolicy || DEFAULT_CONTACT_POLICY;
  const source = (opts && opts.source) || "csv";
  const flatConfidence = (opts && opts.confidence != null) ? opts.confidence : 80;
  const confidenceByField = (opts && opts.confidenceByField) || {};
  const evidence = (opts && opts.evidence) || {};
  const verifiedAt = _nowIso();

  const canonicalPatch = {};
  const provenance = {};
  const cacheKeys = {};
  const decisions = [];

  for (const field of Object.keys(candidateRow)) {
    const value = candidateRow[field];
    if (_isBlank(value)) continue; // nothing to merge

    const currentValue = existingProps[field];
    const fieldPol = policy[field] || { class: "fill_blank_only", min_confidence: 80 };
    const evidenceUrl = evidence[field];
    // The resolved per-field value is used EVERYWHERE the flat one used to be — the gate
    // threshold, the provenance entry, and the decision record — so the recorded
    // confidence and the confidence that made the decision can never disagree.
    const confidence = confidenceByField[field] != null ? confidenceByField[field] : flatConfidence;

    const gate = _gate(field, currentValue, confidence, fieldPol, evidenceUrl, value);
    let decision = gate.decision;

    // HARD GUARD: email never promotes to canonical on the enrich path.
    if (field === "email" && decision === "promote") decision = "stage_only";

    const validationStatus = _statusFor(decision);

    // ONE provenance entry per field — replaces the old flat metadataPatch/stagingPatch.
    const entry = { source, confidence, verified_at: verifiedAt,
                    validation_status: validationStatus, value };
    if (!_isBlank(evidenceUrl)) entry.evidence_url = evidenceUrl;
    provenance[field] = entry;

    if (decision === "promote") {
      canonicalPatch[field] = value;
      // STALE-TIMESTAMP FIX (Phase 16.2 gpt #6): the cache-key datetime is stamped ONLY
      // when the field is actually ACCEPTED — moved inside this branch (was previously
      // unconditional) so a needs_review/stale-but-unpromoted candidate is never marked
      // fresh, which would otherwise suppress the next stale-refresh check forever.
      // Mirrored onto mergeCompanies.js in Phase 16.3 — both paths now carry the fix.
      if (CONTACT_CACHE_KEY_FIELDS[field]) {
        cacheKeys[CONTACT_CACHE_KEY_FIELDS[field]] = verifiedAt;
      }
    }

    decisions.push({
      field,
      current_value: currentValue === undefined ? null : currentValue,
      chosen_value: value,
      source_provider: source,
      decision,
      confidence,
      reason: gate.reason,
      validation_status: validationStatus,
      evidence_url: _isBlank(evidenceUrl) ? null : evidenceUrl,
      verified_at: verifiedAt,
    });
  }

  return { canonicalPatch, provenance, cacheKeys, decisions };
}

// foldContactResearch(providerMerge, researchMerge, judgePromotedFields, existingRecord)
// -> {canonicalPatch, provenance, cacheKeys, decisions} — Phase 16.2 (SC-3) fold of a
// SECOND mergeContacts() result (the Claude web-research candidate, jobtitle/seniority)
// into the provider merge's result. This is a WRITE-SAFETY GATE, NOT adjudication (the
// judge already adjudicated any existing-record conflict upstream) — for each field the
// research candidate carries a decision for, research wins ONLY when:
//   (a) the judge PROMOTED it (field is in judgePromotedFields, the fresh chain-set
//       marker derived from applyContactJudgeVerdict's judge_flags.promoted_field — NEVER
//       the caller-injectable judge_confidence_by_field), OR
//   (b) it fills a GENUINE gap: the provider produced no canonical value for the field
//       AND the existing HubSpot record is also blank there (kimi HIGH-2 — provider-
//       absent alone is not a gap when the existing record already holds a value).
// Otherwise the provider/existing value stands, and the withheld research decision is
// rewritten to stage_only/"withheld_by_overlap_precedence" so the audit trail
// (decisions) agrees with the actual canonicalPatch (gpt #8).
function foldContactResearch(providerMerge, researchMerge, judgePromotedFields, existingRecord) {
  const provider = providerMerge || {};
  const research = researchMerge || {};
  const providerCanonical = provider.canonicalPatch || {};
  const researchCanonical = research.canonicalPatch || {};
  const researchProvenance = research.provenance || {};
  const researchCacheKeys = research.cacheKeys || {};
  const promoted = judgePromotedFields || [];
  const existing = existingRecord || {};

  const canonicalPatch = { ...providerCanonical };
  const provenance = { ...(provider.provenance || {}) };
  const cacheKeys = { ...(provider.cacheKeys || {}) };
  const decisions = [...(provider.decisions || [])];

  for (const decision of (research.decisions || [])) {
    const field = decision.field;
    const judgePromoted = promoted.indexOf(field) !== -1;
    const providerHasField = Object.prototype.hasOwnProperty.call(providerCanonical, field);
    const genuineGap = !providerHasField && _isBlank(existing[field]);
    const researchWins = judgePromoted || genuineGap;

    if (!researchWins) {
      decisions.push({ ...decision, decision: "stage_only", reason: "withheld_by_overlap_precedence" });
      continue;
    }

    decisions.push(decision);
    if (decision.decision !== "promote") continue; // researchWins but its own gate withheld it

    canonicalPatch[field] = researchCanonical[field];
    provenance[field] = researchProvenance[field];
    const cacheKeyName = CONTACT_CACHE_KEY_FIELDS[field];
    if (cacheKeyName && cacheKeyName in researchCacheKeys) {
      cacheKeys[cacheKeyName] = researchCacheKeys[cacheKeyName];
    }
  }

  return { canonicalPatch, provenance, cacheKeys, decisions };
}

// --- n8n wrapper: mergeContacts(existingRecord, winners) non-clobber ---
// PN-1: linkedin_url is NOT HubSpot-native -> the merge candidate/canonical key is
// lv_linkedin_url. `winners.linkedin_url` (the scoreCandidates winner key, if a provider
// mapper ever populates it) stays unprefixed on the READ side, unrelated to this rename.
return $input.all().map((it) => {
  const row = it.json;
  if (!row.scored) return { json: { ...row, merge: null } };  // skip branch
  const winners = row.scored.winners || {};
  const candidate = {};
  for (const f of ["email", "mobilephone", "phone", "jobtitle", "seniority"]) {
    if (winners[f] != null && String(winners[f]).trim() !== "") candidate[f] = winners[f];
  }
  if (winners.linkedin_url != null && String(winners.linkedin_url).trim() !== "") {
    candidate.lv_linkedin_url = winners.linkedin_url;
  }
  // COPY-02: persona_group is NOT HubSpot-native (PN-1) -> the merge candidate/canonical
  // key is lv_persona_group. Dot-property access only, never a bare quoted array entry
  // (the PN-1 architecture guard forbids a bare quoted persona_group string literal here).
  if (winners.persona_group != null && String(winners.persona_group).trim() !== "") {
    candidate.lv_persona_group = winners.persona_group;
  }
  const merged = mergeContacts(row.existingRecord || {}, candidate, undefined,
                               { source: "waterfall", confidence: 85 });

  // Phase 16.2 (SC-3 honest mirror, D6 analog): fold the Claude web-research candidate
  // (jobtitle/seniority ONLY) in as a SECOND mergeContacts() call, then reconcile any
  // overlap with the provider merge via foldContactResearch's write-SAFETY gate (never
  // adjudication — the judge already adjudicated any existing-record conflict upstream).
  // A no-op for every row this module didn't add a contact research chain for (LOCAL,
  // which never sets research_candidate) and for a companies row (rc undefined there).
  let finalMerge = merged;
  const rc = row.research_candidate;
  if (rc && rc.matched) {
    const researchData = {};
    for (const f of ["jobtitle", "seniority"]) {
      const v = rc.data && rc.data[f];
      if (v === null || v === undefined || v === "" || (Array.isArray(v) && v.length === 0)) continue;
      researchData[f] = v;
    }
    if (Object.keys(researchData).length > 0) {
      // LOW-9: require_evidence_url:true on BOTH fields, belt-and-braces on top of the
      // upstream validate-time evidence demotion (contactResearch.js) — a research value
      // can promote only WITH evidence at every layer that touches it. jobtitle also
      // moves to system_owned (overriding its DEFAULT_CONTACT_POLICY stale_refreshable
      // class) so a research-sourced value is not blocked by the "existing value present
      // -> needs_review" refresh rule that class carries for provider data.
      const RESEARCH_POLICY = {
        ...DEFAULT_CONTACT_POLICY,
        jobtitle: { class: "system_owned", min_confidence: 75, require_evidence_url: true },
        seniority: { ...DEFAULT_CONTACT_POLICY.seniority, require_evidence_url: true },
      };
      const researchMerged = mergeContacts(row.existingRecord || {}, researchData, RESEARCH_POLICY,
        { source: "claude_web", confidence: rc.confidence || 80, evidence: rc.evidence_by_field || {},
          confidenceByField: row.judge_confidence_by_field || {} });
      // The ONLY trusted per-field adjudication signal — set fresh by the security-
      // hardened applyContactJudgeVerdict, never the caller-injectable
      // judge_confidence_by_field (gpt #5/#8).
      const judgePromotedFields = (rc.judge_flags && rc.judge_flags.promoted_field)
        ? [rc.judge_flags.promoted_field] : [];
      finalMerge = foldContactResearch(merged, researchMerged, judgePromotedFields, row.existingRecord || {});
    }
  }

  return { json: { ...row, merge: finalMerge } };
});

// Decide Action (dry-run echo) — LOCAL variant.
// Replaces the HubSpot create/update write nodes: ECHOES the would-be payload,
// performs NO real write. Surfaces the per-identity action + scored winners w/ provenance.
// Phase 15: this is the SINGLE serialization point for the provenance blob — the
// stamper (mergeContacts.js) returns the parsed provenance object, never a string.
function _sortedForStringify(v) {
  if (Array.isArray(v)) return v.map(_sortedForStringify);
  if (v !== null && typeof v === "object") {
    const out = {};
    for (const k of Object.keys(v).sort()) out[k] = _sortedForStringify(v[k]);
    return out;
  }
  return v;
}
function _stableStringify(v) { return JSON.stringify(_sortedForStringify(v)); }
function _buildContactPatch(merge) {
  if (!merge) return {};
  const patch = { ...merge.canonicalPatch, ...(merge.cacheKeys || {}) };
  if (merge.provenance && Object.keys(merge.provenance).length) {
    patch.lv_contact_enrichment_provenance = _stableStringify(merge.provenance).slice(0, 60000);
  }
  return patch;
}

return $input.all().map((it) => {
  const row = it.json;
  const action = row.action;
  const id = row.identity_keys || {};
  const scored = row.scored;
  const winners_sample = [];
  if (scored && scored.best) {
    for (const f of Object.keys(scored.best)) {
      const b = scored.best[f];
      winners_sample.push({ field: f, value: b.value, source: b.source,
        score: Math.round(b.score * 100) / 100, agreedBy: b.agreedBy });
    }
  }
  const patch = { ..._buildContactPatch(row.merge), ...(row.lusha_ids || {}) };
  let hubspot_op = null;
  if (action === "create") {
    // BUG 19: seed identity on create ONLY — canonicalPatch never carries email
    // (manual_protected), and a record created without it is invisible to the search
    // that gated the create.
    if (id.email || row.email) patch.email = id.email || row.email;
    hubspot_op = { method: "POST", endpoint: "/crm/v3/objects/contacts", properties: patch };
  } else if (action === "enrich") {
    hubspot_op = { method: "PATCH", endpoint: "/crm/v3/objects/contacts/{id}", properties: patch };
  } // skip -> no op
  return { json: {
    email: id.email || row.email || null,
    action,
    gate_reason: row.gate ? row.gate.reason : null,
    gap_flag: row.gap_flag === true,
    winners_sample,
    dry_run: true,
    hubspot_op
  }};
});
